<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class ImageScanner implements SiteDoctorScanner{public function id():string{return 'images';}public function label():string{return 'Images';}public function scan():array{$o=[];$posts=get_posts(['post_type'=>['post','page'],'post_status'=>'publish','posts_per_page'=>10,'fields'=>'ids']);$missing=0;foreach($posts as $id){$content=get_post_field('post_content',$id);if(preg_match_all('/<img(?![^>]*\balt=)[^>]*>/i',$content,$m))$missing+=count($m[0]);}if($missing)$o[]=$this->i('content-images-without-alt','images','medium','safe','Content images without ALT detected','At least '.$missing.' content image(s) in the sampled pages/posts lack ALT attributes.','Add descriptive ALT text where images convey information.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
